import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor list and degree array
    if is_matrix:
        neighbors = []
        deg = [0] * n
        for i in range(n):
            row = adj[i]
            nbrs = []
            for j in range(n):
                if row[j] == 1:
                    nbrs.append(j)
            neighbors.append(nbrs)
            deg[i] = len(nbrs)
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid side effects
        deg = [len(lst) for lst in neighbors]

    # Trivial cases: edgeless or complete graph
    if all(d == 0 for d in deg):
        return [0] * n
    if all(d == n - 1 for d in deg):
        return list(range(n))

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR coloring (returns color array)
    def dsatur():
        color = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))

        if not uncolored:
            return color
        # Initial vertex: highest degree
        v = max(uncolored, key=lambda x: deg[x])
        color[v] = 0
        saturated[v].add(0)
        uncolored.remove(v)
        for u in neighbors[v]:
            saturated[u].add(0)

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
            v = max(uncolored, key=lambda x: (
                len(saturated[x]),
                sum(1 for u in neighbors[x] if u in uncolored),
                -x
            ))
            used = [False] * n
            for c in saturated[v]:
                used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                saturated[u].add(c)
        return color

    # Helper: RLF (Recursive Largest First) coloring
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))
            S = {v}
            # U: not adjacent to S, W: adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(u in neighbors[w] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U, then index
                u = max(U, key=lambda x: (
                    sum(1 for w in neighbors[x] if w in W),
                    -sum(1 for w in neighbors[x] if w in U),
                    -x
                ))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Kempe chain local search to reduce colors (optimized for speed and correctness)
    def kempe_reduce(color_in):
        color = color_in[:]
        if n == 0:
            return color
        k = max(color) + 1
        if k <= 1:
            return color
        improved = True
        iteration_limit = 6  # Balanced for effectiveness and speed
        for _ in range(iteration_limit):
            if not improved:
                break
            improved = False
            # Try to eliminate color classes from highest to lowest
            for target_color in range(k - 1, 0, -1):
                verts = [v for v in range(n) if color[v] == target_color]
                if not verts:
                    continue
                # Process vertices in random order to avoid worst-case behavior
                random.shuffle(verts)
                for v in verts:
                    # Try direct recolor to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if color[u] != -1:
                            neighbor_colors.add(color[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            improved = True
                            break
                    if improved:
                        # After a change, break to restart scanning from highest color
                        break
                    # Try Kempe chains
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # BFS to find Kempe chain component of v in colors {target_color, c}
                        visited = [False] * n
                        stack = [v]
                        visited[v] = True
                        component = []
                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for u in neighbors[node]:
                                if not visited[u] and color[u] in (target_color, c):
                                    visited[u] = True
                                    stack.append(u)
                        # Check if any neighbor of v with color c is in this component
                        has_c_neighbor_in_comp = False
                        for u in neighbors[v]:
                            if color[u] == c and visited[u]:
                                has_c_neighbor_in_comp = True
                                break
                        if not has_c_neighbor_in_comp:
                            # Swap colors in component
                            for node in component:
                                if color[node] == target_color:
                                    color[node] = c
                                elif color[node] == c:
                                    color[node] = target_color
                            improved = True
                            break
                    if improved:
                        break
                else:
                    # Only executed if inner loop did NOT break (i.e., no improvement for this target_color)
                    continue
                # Break out of target_color loop to restart from highest color after any improvement
                break
            # Recompute k after possible reduction
            k = max(color) + 1 if n > 0 else 0
        return color

    # Generate initial colorings using multiple heuristics (optimized set)
    orders = []
    orders.append(list(range(n)))  # natural
    orders.append(list(range(n - 1, -1, -1)))  # reverse
    orders.append(sorted(range(n), key=lambda v: (-deg[v], v)))  # Welsh-Powell (desc degree)
    # Recompute SL peeling order for use in greedy
    def sl_peeling_order():
        deg_sl = deg[:]
        alive = [True] * n
        order = []
        max_deg = max(deg_sl) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_sl[v]
            if d <= max_deg:
                buckets[d].append(v)
        min_deg = 0
        for _ in range(n):
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            while not alive[v]:
                if not buckets[min_deg]:
                    min_deg += 1
                    while min_deg <= max_deg and not buckets[min_deg]:
                        min_deg += 1
                    if min_deg > max_deg:
                        break
                    v = buckets[min_deg].pop()
                else:
                    v = buckets[min_deg].pop()
            order.append(v)
            alive[v] = False
            for u in neighbors[v]:
                if alive[u]:
                    d = deg_sl[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    deg_sl[u] -= 1
                    d_new = deg_sl[u]
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        return order  # peeling order (smallest last first)
    sl_order = sl_peeling_order()
    orders.append(sl_order)
    orders.append(sorted(range(n), key=lambda v: deg[v]))  # ascending degree

    colorings = []

    # Greedy on various orders
    for order in orders:
        colorings.append(greedy_color(order))

    # Direct heuristics (only the most effective ones to save time)
    colorings.append(dsatur())
    colorings.append(rlf())

    # Very limited random restarts
    for _ in range(3):  # Balanced for exploration and speed
        order = list(range(n))
        random.shuffle(order)
        colorings.append(greedy_color(order))

    # Select the coloring with the fewest colors
    def num_colors(c):
        return max(c) + 1 if n > 0 else 0

    best_coloring = min(colorings, key=num_colors)

    # Apply Kempe chain reduction to try to improve
    best_coloring = kempe_reduce(best_coloring)

    return best_coloring

