import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (binary square matrix)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = []
        degree = [0] * n
        for i in range(n):
            row = []
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
                    degree[i] += 1
            adj_list.append(row)
    else:
        adj_list = adj
        degree = [len(adj_list[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Strategy 1: DSATUR with independent set extraction per color (hybrid)
    def dsatur_independent_set():
        color = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        color_class = 0
        while not all(colored):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg_uncolored = -1
            candidates = []
            for i in range(n):
                if not colored[i]:
                    deg_uncolored = 0
                    for u in adj_list[i]:
                        if not colored[u]:
                            deg_uncolored += 1
                    if saturation[i] > max_sat:
                        max_sat = saturation[i]
                        max_deg_uncolored = deg_uncolored
                        candidates = [i]
                    elif saturation[i] == max_sat:
                        if deg_uncolored > max_deg_uncolored:
                            max_deg_uncolored = deg_uncolored
                            candidates = [i]
                        elif deg_uncolored == max_deg_uncolored:
                            candidates.append(i)
            if not candidates:
                break
            v = random.choice(candidates)
            # Build maximal independent set starting with v
            S = [v]
            colored[v] = True
            R = [i for i in range(n) if not colored[i]]
            U = []
            W = []
            for u in R:
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.append(u)
                else:
                    U.append(u)
            W_set = set(W)
            # Grow independent set S by selecting vertices from U
            while U:
                best_u = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                U_set = set(U)
                for u in U:
                    count = 0
                    for w in adj_list[u]:
                        if w in W_set:
                            count += 1
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U_set:
                            deg_in_U += 1
                    if count > max_neighbors_in_W or (count == max_neighbors_in_W and deg_in_U < min_deg_in_U):
                        max_neighbors_in_W = count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        if w not in W_set:
                            W.append(w)
                            W_set.add(w)
            # Assign current color to all vertices in independent set S
            for vertex in S:
                color[vertex] = color_class
            color_class += 1
            # Update saturation for uncolored neighbors of newly colored vertices
            for u in S:
                for w in adj_list[u]:
                    if not colored[w]:
                        found = False
                        for x in adj_list[w]:
                            if colored[x] and color[x] == color[u]:
                                found = True
                                break
                        if not found:
                            saturation[w] += 1
        return color

    # Strategy 2: Pure DSATUR (vertex-by-vertex)
    def dsatur_vertex():
        color = [-1] * n
        saturation = [0] * n
        colored = [False] * n
        for _ in range(n):
            v = -1
            max_sat = -1
            max_deg_uncolored = -1
            candidates = []
            for i in range(n):
                if not colored[i]:
                    deg_uncolored = 0
                    for u in adj_list[i]:
                        if not colored[u]:
                            deg_uncolored += 1
                    if saturation[i] > max_sat:
                        max_sat = saturation[i]
                        max_deg_uncolored = deg_uncolored
                        candidates = [i]
                    elif saturation[i] == max_sat:
                        if deg_uncolored > max_deg_uncolored:
                            max_deg_uncolored = deg_uncolored
                            candidates = [i]
                        elif deg_uncolored == max_deg_uncolored:
                            candidates.append(i)
            if not candidates:
                break
            v = random.choice(candidates)
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            for u in adj_list[v]:
                if not colored[u]:
                    found = False
                    for w in adj_list[u]:
                        if colored[w] and color[w] == c:
                            found = True
                            break
                    if not found:
                        saturation[u] += 1
        return color

    # Strategy 3: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        colored = [False] * n
        color_class = 0
        while not all(colored):
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            deg_in_R = [0] * n
            for v in R:
                for u in adj_list[v]:
                    if not colored[u]:
                        deg_in_R[v] += 1
            v = max(R, key=lambda x: deg_in_R[x])
            S = [v]
            colored[v] = True
            U = []
            W = []
            for u in R:
                if u == v:
                    continue
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.append(u)
                else:
                    U.append(u)
            W_set = set(W)
            while U:
                best_u = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                U_set = set(U)
                for u in U:
                    count = 0
                    for w in adj_list[u]:
                        if w in W_set:
                            count += 1
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U_set:
                            deg_in_U += 1
                    if count > max_neighbors_in_W or (count == max_neighbors_in_W and deg_in_U < min_deg_in_U):
                        max_neighbors_in_W = count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        if w not in W_set:
                            W.append(w)
                            W_set.add(w)
            for vertex in S:
                color[vertex] = color_class
            color_class += 1
        return color

    # Strategy 4: Welsh-Powell
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    # Strategy 5: Smallest-Last ordering
    def smallest_last():
        remaining = set(range(n))
        order = []
        deg = degree[:]
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    deg[u] -= 1
        return greedy_color(order[::-1])

    # Try all strategies and pick the one with fewest colors
    strategies = [dsatur_independent_set, dsatur_vertex, rlf, welsh_powell, smallest_last]
    best_coloring = None
    best_num_colors = float('inf')
    for strategy in strategies:
        try:
            coloring = strategy()
            num = num_colors(coloring)
            if num < best_num_colors:
                best_num_colors = num
                best_coloring = coloring
        except Exception:
            continue

    # Fallback: if all failed, use greedy with natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    return best_coloring
